  "name": "button-webapp",
  "version": "1.0.0",
  "description": "Pequeno sistema web com botão funcional e teste automatizado",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "test": "jest"
  },
  "author": "",
  "license": "MIT",
  "dependencies": {
