```

---  

### 3. Implementar `server.js`
```javascript
// server.js
const express = require('express');
const path = require('path');

const app = express();
const PORT = process.env.PORT || 3000;

// Middleware para interpretar JSON no corpo das requisições
app.use(express.json());

// Servir arquivos estáticos da pasta "public"
app.use(express.static(path.join(__dirname, 'public')));

// Endpoint que será chamado ao clicar no botão
app.post('/api/button', (req, res) => {
  // Podemos receber dados, mas aqui apenas retornamos confirmação
  res.json({ status: 'clicked' });
});

// Rota fallback para garantir que qualquer caminho desconhecido retorne index.html
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Servidor rodando em http://localhost:${PORT}`);
});

module.exports = app; // Exporta para uso nos testes
```

---  

### 4. Criar front‑end `public/index.html`
```html
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <title>Botão Funcional</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 2rem; }
    #status { margin-top: 1rem; color: green; }
  </style>
</head>
<body>
  <h1>Teste de Botão</h1>
  <button id="myButton">Clique aqui</button>
  <div id="status"></div>

  <script>
    const button = document.getElementById('myButton');
    const statusDiv = document.getElementById('status');

    button.addEventListener('click', async () => {
      try {
        const response = await fetch('/api/button', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({}) // corpo vazio, apenas para demonstrar
        });
        const data = await response.json();
        statusDiv.textContent = `Servidor respondeu: ${data.status}`;
      } catch (err) {
        statusDiv.textContent = 'Erro ao comunicar com o servidor';
        console.error(err);
      }
    });
  </script>
</body>
</html>
```

