};
```

---  

### 6. Escrever testes automatizados `test/server.test.js`
```javascript
// test/server.test.js
const request = require('supertest');
const app = require('../server'); // importa o servidor Express

describe('Teste de integração da aplicação', () => {
  test('GET / deve retornar a página HTML contendo o botão', async () => {
    const res = await request(app).get('/');
    expect(res.statusCode).toBe(200);
    expect(res.headers['content-type']).toMatch(/html/);
    expect(res.text).toContain('id="myButton"');
  });

  test('POST /api/button deve responder com JSON {status:"clicked"}', async () => {
    const res = await request(app)
      .post('/api/button')
      .send({}); // corpo vazio
    expect(res.statusCode).toBe(200);
    expect(res.headers['content-type']).toMatch(/json/);
    expect(res.body).toEqual({ status: 'clicked' });
  });
});
```

---  

### 7. Instalar dependências e validar testes
**Ação:** instalar pacotes e rodar `npm test`.

```bash
npm install
npm test
```

