```python
# server.js
write_file("/Users/tiagosantos/Desktop/criador/workspace/e2e_rc29_resilience_d317d2d3/server.js", """const express = require('express');
const app = express();
app.use(express.json());

// Dados em memória (sem persistência)
let items = [];
let nextId = 1;

// CREATE
app.post('/items', (req, res) => {
  const { name } = req.body;
  if (!name) {
    return res.status(400).json({ error: 'Campo "name" é obrigatório.' });
  }
  const item = { id: nextId++, name };
  items.push(item);
  res.status(201).json(item);
});

// READ ALL
app.get('/items', (req, res) => {
  res.json(items);
});

// READ ONE
app.get('/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const item = items.find(i => i.id === id);
  if (!item) {
    return res.status(404).json({ error: 'Item não encontrado.' });
  }
  res.json(item);
});

// UPDATE
app.put('/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const { name } = req.body;
  const item = items.find(i => i.id === id);
  if (!item) {
    return res.status(404).json({ error: 'Item não encontrado.' });
  }
  if (!name) {
    return res.status(400).json({ error: 'Campo "name" é obrigatório.' });
  }
  item.name = name;
  res.json(item);
});

// DELETE
app.delete('/items/:id', (req, res) => {
  const id = parseInt(req.params.id);
  const index = items.findIndex(i => i.id === id);
  if (index === -1) {
    return res.status(404).json({ error: 'Item não encontrado.' });
  }
  const removed = items.splice(index, 1)[0];
  res.json(removed);
});

// Exporta app para testes
module.exports = app;

// Inicia servidor apenas se o arquivo for executado diretamente
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Servidor rodando na porta ${PORT}`);
  });
}
""")
```

```python
# test/server.test.js
write_file("/Users/tiagosantos/Desktop/criador/workspace/e2e_rc29_resilience_d317d2d3/test/server.test.js", """const request = require('supertest');
const app = require('../server');

describe('CRUD de /items', () => {
  let createdId;

  test('POST /items cria um item', async () => {
    const res = await request(app)
      .post('/items')
      .send({ name: 'Item de teste' })
      .expect(201);
    expect(res.body).toHaveProperty('id');
    expect(res.body.name).toBe('Item de teste');
    createdId = res.body.id;
  });

  test('GET /items retorna lista contendo o item criado', async () => {
    const res = await request(app).get('/items').expect(200);
    const ids = res.body.map(i => i.id);
    expect(ids).toContain(createdId);
  });

  test('GET /items/:id retorna o item correto', async () => {
    const res = await request(app).get(`/items/${createdId}`).expect(200);
    expect(res.body.id).toBe(createdId);
    expect(res.body.name).toBe('Item de teste');
  });

  test('PUT /items/:id atualiza o item', async () => {
    const res = await request(app)
      .put(`/items/${createdId}`)
      .send({ name: 'Item atualizado' })
      .expect(200);
    expect(res.body.name).toBe('Item atualizado');
  });

  test('DELETE /items/:id remove o item', async () => {
    await request(app).delete(`/items/${createdId}`).expect(200);
    // Verifica que não existe mais
    await request(app).get(`/items/${createdId}`).expect(404);
  });
});
""")
```

